<script lang="ts">import{resolveConversationSide,type BubbleGroupSpacing,type ConversationSide}from'@fex-design/core/bubble/types';import{bubbleGroupClassName}from'@fex-design/styles/bubble';import{cn}from'@fex/utils';import{getContext,type Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';import{messageSideContextKey}from'./context';interface Props extends HTMLAttributes<HTMLDivElement>{side?:ConversationSide;spacing?:BubbleGroupSpacing;children?:Snippet}let{side:sideProp,spacing='default',class:className,children,...rest}:Props=$props();const inherited=getContext<(()=>ConversationSide)|undefined>(messageSideContextKey);let side=$derived(resolveConversationSide(sideProp,inherited?.()))</script>
<div {...rest} data-slot="bubble-group" data-side={side} data-spacing={spacing} class={cn(bubbleGroupClassName({spacing}),className)}>{@render children?.()}</div>
